  ('mentone', 'mentone', 'Mentone', 'Panel Beater Mentone | Smash Repairs Mentone | CA Autobody', 'Professional smash repair and panel beating support for drivers in Mentone and surrounding Melbourne suburbs.', '["CA Autobody supports Mentone drivers with accident repair, panel beating, refinishing and related repair services from our Chelsea Heights workshop.","Our focus is a clear repair process, careful workmanship and practical communication from the first assessment through to vehicle handover."]'::jsonb, '/images/Banner.webp', '[-37.9826,145.0657]'::jsonb, 'Repair guidance and workshop support for Mentone motorists.', 'published', 6),
  ('mordialloc', 'mordialloc', 'Mordialloc', 'Panel Beater Mordialloc | Smash Repairs Mordialloc | CA Chelsea Autobody', 'Professional smash repair and panel beating support for drivers in Mordialloc and surrounding Melbourne suburbs.', '["CA Autobody supports Mordialloc drivers with accident repair, panel beating, refinishing and related repair services from our Chelsea Heights workshop.","Our focus is a clear repair process, careful workmanship and practical communication from the first assessment through to vehicle handover."]'::jsonb, '/images/Banner.webp', '[-38.0058,145.0867]'::jsonb, 'Bayside body repair and refinishing support for Mordialloc.', 'published', 7),
  ('parkdale', 'parkdale', 'Parkdale', 'Panel Beater Parkdale | Smash Repairs Parkdale | CA Chelsea Autobody', 'Professional smash repair and panel beating support for drivers in Parkdale and surrounding Melbourne suburbs.', '["CA Autobody supports Parkdale drivers with accident repair, panel beating, refinishing and related repair services from our Chelsea Heights workshop.","Our focus is a clear repair process, careful workmanship and practical communication from the first assessment through to vehicle handover."]'::jsonb, '/images/Banner.webp', '[-37.9912,145.0802]'::jsonb, 'Repair assessment and accident assistance for Parkdale drivers.', 'published', 8),
