insert into public.cms_offers (legacy_key, slug, title, seo_title, eyebrow, intro, body, image_path, bullets, status, sort_order) values
  ('byd-approved-repairer-melbourne', 'byd-approved-repairer-melbourne', 'BYD Approved Repairer Melbourne', 'BYD Approved Repairer Melbourne - CA Chelsea Autobody', 'BYD Repair', 'Specialist repair support for modern BYD electric vehicles.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/close-up-of-electric-car-charging-ecology-transpo-2026-03-10-03-08-40-utc.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 0),
  ('fleet-and-commercial-repairs', 'fleet-and-commercial-repairs', 'Fleet And Commercial Repairs', 'Fleet And Commercial Repairs - CA Chelsea Autobody', 'Fleet Repairs', 'A practical repair pathway for fleet and commercial vehicles where uptime and communication matter.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/Replacement-Vehicles.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 1),
  ('lexus-approved-body-shop-melbourne', 'lexus-approved-body-shop-melbourne', 'Lexus Approved Body Shop Melbourne', 'Lexus Approved Body Shop Melbourne - CA Chelsea Autobody', 'Lexus Repair', 'Premium collision repair support for Lexus vehicles with careful body and paint finishing.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/mechanic-inspects-auto-body-damage-in-automotive-s-2026-01-07-06-40-31-utc.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 2),
  ('not-at-fault-accident-repairs', 'not-at-fault-accident-repairs', 'Not At Fault Accident Repairs', 'Not At Fault Accident Repairs - CA Chelsea Autobody', 'Not At Fault', 'Guidance and repair support when you have been involved in an accident that was not your fault.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/ACCIDENT-ASSISTANCE-1.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 3),
  ('tesla-approved-body-shop-melbourne', 'tesla-approved-body-shop-melbourne', 'Tesla Approved Body Shop Melbourne', 'Tesla Approved Body Shop Melbourne - CA Chelsea Autobody', 'Tesla Repair', 'Specialist accident repair support for Tesla owners in Melbourne.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/tesla-repair.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 4),
  ('zeekr-authorised-repairer-melbourne', 'zeekr-authorised-repairer-melbourne', 'Zeekr Authorised Repairer Melbourne', 'Zeekr Authorised Repairer Melbourne - CA Chelsea Autobody', 'Zeekr Repair', 'Specialist repair support for advanced Zeekr electric vehicles.', '["Modern collision repair requires a controlled process, the right repair approach and clear communication throughout the job.","CA Autobody combines experienced technicians, a well-equipped Chelsea Heights facility and customer-focused repair coordination from assessment to handover."]'::jsonb, '/images/Chelsea-Auto-Body-009.webp', '["Initial assessment","Repair planning","Body and refinishing work","Final quality review"]'::jsonb, 'published', 5)
insert into public.cms_blog_posts (legacy_key, slug, title, category, display_date, excerpt, image_path, blocks, status, sort_order) values
  ('what-details-should-you-have-ready-before-booking-accident-repairs', 'what-details-should-you-have-ready-before-booking-accident-repairs', 'What Details Should You Have Ready Before Booking Accident Repairs?', 'CA Knows', '18 September 2026', 'Booking accident repairs? Have vehicle details, impact location, photos, claim status and the car''s current location ready before calling the workshop team.', '/images/homepage-Accident-Assistance.webp', '[]'::jsonb, 'published', 0),
  ('what-should-you-ask-before-choosing-a-tesla-collision-repairer', 'what-should-you-ask-before-choosing-a-tesla-collision-repairer', 'What Should You Ask Before Choosing a Tesla Collision Repairer?', 'CA Knows', '7 September 2026', 'Approval status, repair experience, replacement parts, communication and the repair process can all help you choose a Tesla collision repairer.', '/images/tesla-repair.webp', '[]'::jsonb, 'published', 1),
  ('can-a-damaged-car-panel-be-repaired-or-does-it-need-replacing', 'can-a-damaged-car-panel-be-repaired-or-does-it-need-replacing', 'Can a Damaged Car Panel Be Repaired or Does It Need Replacing?', 'CA Knows', '19 August 2026', 'Key checks on dents, paint, mounting points and collision damage can help determine whether a panel is repaired or replaced.', '/images/PANEL-BEATING.webp', '[]'::jsonb, 'published', 2),
  ('what-happens-after-your-tesla-is-damaged-in-an-accident', 'what-happens-after-your-tesla-is-damaged-in-an-accident', 'What Happens After Your Tesla Is Damaged in an Accident?', 'CA Knows', '27 July 2026', 'From assessment and panel work to paint, insurance details and final checks, understand the stages after Tesla accident damage.', '/images/tesla-repair-centre.webp', '[]'::jsonb, 'published', 3),
  ('what-melbourne-drivers-should-know-about-paintless-dent-removal', 'what-melbourne-drivers-should-know-about-paintless-dent-removal', 'What Melbourne Drivers Should Know About Paintless Dent Removal', 'CA Knows', '10 June 2026', 'Paintless dent removal can help repair suitable small dents while preserving factory paint, depending on access and panel condition.', '/images/PAINTLESS-DENT-REMOVAL.webp', '[]'::jsonb, 'published', 4),
  ('what-should-you-ask-before-choosing-a-panel-beater-in-sandhurst', 'what-should-you-ask-before-choosing-a-panel-beater-in-sandhurst', 'What Should You Ask Before Choosing a Panel Beater in Sandhurst?', 'CA Knows', '19 May 2026', 'Ask about repair methods, warranties, communication, experience and replacement parts before choosing a repairer.', '/images/panel-beatingimg.webp', '[]'::jsonb, 'published', 5),
  ('smart-drivers-guide-to-finding-a-trustworthy-panel-beater-in-braeside', 'smart-drivers-guide-to-finding-a-trustworthy-panel-beater-in-braeside', 'The Smart Driver''s Guide to Finding a Trustworthy Panel Beater in Braeside', 'CA Knows', '16 January 2026', 'A practical guide to reputation, communication and repair quality when choosing a local panel beater.', '/images/Chelsea-Auto-Body-031.webp', '[]'::jsonb, 'published', 6),
  ('why-smash-repairs-in-mentone-are-worth-considering', 'why-smash-repairs-in-mentone-are-worth-considering', 'Need Help from a Local Specialist? Here''s Why Smash Repairs in Mentone Are Worth Considering', 'CA Knows', '30 December 2025', 'Local repair support can make communication and the repair journey easier after an accident.', '/images/ACCIDENT-ASSISTANCE-3.webp', '[]'::jsonb, 'published', 7),
  ('what-really-happens-during-an-auto-accident-repair', 'what-really-happens-during-an-auto-accident-repair', 'What Really Happens During an Auto Accident Repair: A Step-by-Step Walkthrough', 'CA Knows', '27 November 2025', 'Understand the repair journey from initial assessment through body work, paint and final quality checks.', '/images/Chelsea-Auto-Body-021.webp', '[]'::jsonb, 'published', 8),
  ('got-a-dent-or-scratch-when-to-call-panel-beaters-in-carrum', 'got-a-dent-or-scratch-when-to-call-panel-beaters-in-carrum', 'Got a Dent or Scratch? Here''s When to Call Panel Beaters in Carrum', 'CA Knows', '21 October 2025', 'Know when dents, scratches or collision damage should be professionally assessed and repaired.', '/images/PANEL-BEATING.webp', '[]'::jsonb, 'published', 9)
insert into public.cms_faqs (legacy_key, category, question, answer, is_visible, status, sort_order) values
  ('general-1', 'General', 'How long will my vehicle repair take?', 'Repair times vary depending on the amount of the damage. We work hard to finish repairs on time while maintaining high quality.', true, 'published', 0),
  ('general-2', 'General', 'Can I get a quote before starting repairs?', 'We provide free, no-obligation quotes for all repair services.', true, 'published', 1),
  ('general-3', 'General', 'Do you offer towing services?', 'We provide towing services to move your vehicle to our facility for repair.', true, 'published', 2),
  ('general-4', 'General', 'Do you provide a warranty on repairs?', 'Yes, we back up our work with a lifetime repair warranty.', true, 'published', 3),
  ('general-5', 'General', 'How do I schedule an appointment?', 'Scheduling an appointment is easy. [Contact us](https://caautobody.com.au/contact/) via phone, email, or our website to book your service.', true, 'published', 4),
  ('general-6', 'General', 'Where is CA Autobody located?', 'CA Autobody is located at 7 Ashley Park Drive, Chelsea Heights, VIC 3196. We assist customers across Melbourne, Bayside, Kingston, Frankston and the Mornington Peninsula.', true, 'published', 5),
  ('byd-1', 'BYD', 'Is CA Autobody an Approved BYD Repairer?', 'Yes. CA Autobody is an Approved BYD Repairer in Melbourne. Current BYD approved repairer, confirmed for your model.', true, 'published', 6),
  ('byd-2', 'BYD', 'Will repairs follow BYD procedures?', 'Yes. The repair is planned around manufacturer approved procedures, genuine parts and model specific requirements. The final scope depends on the assessed damage.', true, 'published', 7),
  ('byd-3', 'BYD', 'Can you help if I have not lodged a claim?', 'Yes. Send the vehicle and accident details first so the team can explain the practical repair and claim information you may need.', true, 'published', 8),
  ('byd-4', 'BYD', 'Is a loan car guaranteed?', 'No. Loan or replacement vehicle availability and eligibility must be confirmed for the individual repair or claim.', true, 'published', 9),
  ('byd-5', 'BYD', 'What warranty applies?', 'CA Autobody offers a lifetime workmanship warranty subject to its written warranty terms and exclusions.', true, 'published', 10),
  ('lexus-1', 'Lexus', 'Is CA Autobody a Lexus Approved Repairer?', 'Yes. CA Autobody is a Lexus Approved Repairer in Melbourne. Current Lexus approved repairer, confirmed for your model.', true, 'published', 11),
  ('lexus-2', 'Lexus', 'Do you use genuine Lexus parts?', 'Genuine OEM Lexus parts are specified within the approved repair plan, subject to the repair scope, availability and claim approval.', true, 'published', 12),
  ('lexus-3', 'Lexus', 'Can you assist with an insurance claim?', 'Yes. CA Autobody can help prepare repair information and communicate with the insurer with the customer''s authority.', true, 'published', 13),
  ('lexus-4', 'Lexus', 'Can you arrange towing or a loan car?', 'Towing and loan vehicle options are available. Conditions, availability and eligibility are confirmed for each repair.', true, 'published', 14),
  ('lexus-5', 'Lexus', 'Does the repair include a warranty?', 'CA Autobody offers a lifetime workmanship warranty subject to written terms, exclusions and correct vehicle care.', true, 'published', 15),
  ('insurance-1', 'Insurance', 'How long will my vehicle repair take?', 'Repair times vary depending on the amount of the damage. We work hard to finish repairs on time while maintaining high quality.', true, 'published', 16),
  ('insurance-2', 'Insurance', 'Can I get a quote before starting repairs?', 'We provide free, no-obligation quotes for all repair services.', true, 'published', 17),
  ('insurance-3', 'Insurance', 'Do you offer towing services?', 'We provide towing services to move your vehicle to our facility for repair.', true, 'published', 18),
  ('insurance-4', 'Insurance', 'Do you provide a warranty on repairs?', 'Yes, we back up our work with a lifetime repair warranty.', true, 'published', 19),
  ('original-accident-assistance-1', 'Accident Assistance', 'Do I need to schedule an appointment for accident assistance?', 'Yes, we recommend scheduling an appointment so we can assess the damage and provide you with a detailed estimate for repairs.', true, 'published', 20),
  ('original-accident-assistance-2', 'Accident Assistance', 'What should I do immediately after a car accident?', 'First, ensure everyone is safe, then exchange insurance information with the other driver and take photos of the scene and any damage to your vehicle.', true, 'published', 21),
  ('original-accident-assistance-3', 'Accident Assistance', 'How long will it take to repair my vehicle after an accident?', 'The repair timeframe depends on the extent of the damage, but we’ll provide you with a timeline upfront so you know what to expect.', true, 'published', 22),
  ('original-accident-assistance-4', 'Accident Assistance', 'Are your technicians certified?', 'Yes, our professionals are highly qualified and certified to provide the best repairs for your vehicle.', true, 'published', 23),
  ('original-accident-assistance-5', 'Accident Assistance', 'What types of accident repairs do you offer?', 'We offer a full range of auto accident repair services, including dent repair, panel beating, painting, and more.', true, 'published', 24),
  ('original-paintless-dent-removal-1', 'Paintless Dent Removal', 'What is paintless dent removal?', 'Paintless dent removal is a technique used to repair dents without the need for painting, preserving the original finish of the vehicle.', true, 'published', 25),
  ('original-paintless-dent-removal-2', 'Paintless Dent Removal', 'How long does paintless dent removal take?', 'The time required for paintless dent removal depends on the size and severity of the dent, but it’s typically faster than traditional dent repair methods.', true, 'published', 26),
  ('original-paintless-dent-removal-3', 'Paintless Dent Removal', 'Will paintless dent removal damage my car’s paint?', 'No, paintless dent removal is a non-invasive process that preserves your car’s original paint finish.', true, 'published', 27),
  ('original-paintless-dent-removal-4', 'Paintless Dent Removal', 'Can you remove all dents with paintless dent removal?', 'While paintless dent removal is effective for many types of dents, traditional repair methods may be necessary in some cases.', true, 'published', 28),
  ('original-paintless-dent-removal-5', 'Paintless Dent Removal', 'Can you repair dents on all types of vehicles?', 'Yes, our technicians are experienced in working with all vehicle makes and models, including cars, trucks, and SUVs.', true, 'published', 29),
  ('original-panel-beating-1', 'Panel Beating', 'What is panel beating?', 'Panel beating is the repairing and reshaping of a vehicle’s metal panels damaged in accidents or collisions.', true, 'published', 30),
  ('original-panel-beating-2', 'Panel Beating', 'How long does panel beating take?', 'The duration of panel beating repairs depends on the extent of the damage to your vehicle. Our team will provide an approximate timeframe based on your specific repair needs.', true, 'published', 31),
  ('original-panel-beating-3', 'Panel Beating', 'Can you fix the rust damage on my vehicle?', 'Yes, our panel beaters are experienced in repairing rust damage and can restore your vehicle to its original condition.', true, 'published', 32),
  ('original-panel-beating-4', 'Panel Beating', 'How much does panel beating cost?', 'Panel-beating repairs cost more or less depending on the degree of damage and the particular repair methods needed. Before any maintenance on your car, our staff will send you a comprehensive price.', true, 'published', 33),
  ('original-panel-beating-5', 'Panel Beating', 'Can you match the paint colour of my vehicle?', 'Our technicians use advanced colour-matching technology to ensure a seamless finish matching your vehicle’s original paint colour.', true, 'published', 34),
  ('original-replacement-vehicles-1', 'Replacement Vehicles', 'What is an accident replacement vehicle?', 'An accident replacement vehicle is a temporary rental vehicle provided to individuals whose cars are being repaired following an accident. It allows them to maintain mobility while their vehicle is out of commission.', true, 'published', 35),
  ('original-replacement-vehicles-2', 'Replacement Vehicles', 'How long can I rent an accident replacement vehicle?', 'The rental period for a replacement vehicle typically depends on the duration of repairs to your vehicle. Our team will work with you to find the appropriate rental period based on your needs.', true, 'published', 36),
  ('original-replacement-vehicles-3', 'Replacement Vehicles', 'Are there any age restrictions for renting an accident replacement vehicle?', 'Yes, drivers must meet certain age requirements to rent a vehicle. Please contact us for more information on our age restrictions and rental policies.', true, 'published', 37),
  ('original-replacement-vehicles-4', 'Replacement Vehicles', 'Can I choose the type of vehicle to replace my accident?', 'Yes, we offer various vehicle options to suit your preferences and requirements. Our team will work with you to select the right vehicle for your needs.', true, 'published', 38),
  ('original-spray-painting-1', 'Spray Painting', 'What is car spray painting?', 'Car spray painting is a method of applying paint to a vehicle’s exterior using a spray gun, resulting in a smooth, even finish.', true, 'published', 39),
  ('original-spray-painting-2', 'Spray Painting', 'How long does car spray painting take?', 'The duration of a car spray painting job depends on various factors, including the extent of the work required and the paint drying time. Our team will provide an approximate timeline based on your specific needs.', true, 'published', 40),
  ('original-spray-painting-3', 'Spray Painting', 'Can you match my car’s original paint colour?', 'Our technicians use advanced colour-matching technology to match your car’s original paint colour accurately.', true, 'published', 41),
  ('original-spray-painting-4', 'Spray Painting', 'Do you offer custom paint finishes?', 'Yes, we offer a range of custom paint finishes, including metallic, pearl, and matte options, to help you achieve the perfect look for your vehicle.', true, 'published', 42),
  ('original-spray-painting-5', 'Spray Painting', 'Can you repair scratches and dents before painting?', 'We offer paint correction services to repair scratches, dents, and other imperfections before applying the paint finish.', true, 'published', 43),
  ('original-services-zeekr-approved-repairer-melbourne-1', 'Zeekr', 'Do I need a Zeekr approved repairer after an accident?', 'For modern electric vehicles like Zeekr, it is important to choose a repairer that understands manufacturer repair standards, EV safety requirements, correct parts processes and advanced vehicle technology. This helps protect the quality, safety and value of the vehicle after an accident.', true, 'published', 44),
  ('original-services-zeekr-approved-repairer-melbourne-2', 'Zeekr', 'Can CA Autobody repair Zeekr accident damage?', 'Yes. CA Autobody can assist Zeekr owners with accident repairs, panel beating, spray painting, dent repairs, bumper repairs, insurance repair quoting and replacement vehicle options.', true, 'published', 45),
  ('original-services-zeekr-approved-repairer-melbourne-3', 'Zeekr', 'Can you help with my Zeekr insurance claim?', 'Yes. CA Autobody can assist with the accident repair process, including damage assessment, repair quoting and communication with insurers where required.', true, 'published', 46),
  ('original-services-zeekr-approved-repairer-melbourne-4', 'Zeekr', 'Do you offer replacement vehicles while my Zeekr is being repaired?', 'Yes. CA Autobody offers replacement vehicle options to help keep you on the road while your vehicle is in our care.', true, 'published', 47),
  ('original-services-zeekr-approved-repairer-melbourne-5', 'Zeekr', 'Can you repair Zeekr paint damage?', 'Yes. CA Autobody provides spray painting and colour matching for Zeekr vehicles, including scratch repairs, bumper painting, panel refinishing and paint repairs after collision damage.', true, 'published', 48),
  ('original-services-zeekr-approved-repairer-melbourne-6', 'Zeekr', 'Where is CA Autobody located?', 'CA Autobody is located at 7 Ashley Park Drive, Chelsea Heights, VIC 3196. We assist customers across Melbourne, Bayside, Kingston, Frankston and the Mornington Peninsula.', true, 'published', 49),
  ('byd-question-1', 'BYD', 'Are you officially approved by BYD?', 'Ask for proof that the approval is current and applies to the repair facility.', false, 'retired', 50),
  ('byd-question-2', 'BYD', 'Do you use genuine OEM BYD parts?', 'Confirm the parts plan before authorising work and ask how any exceptions will be explained.', false, 'retired', 51),
  ('byd-question-3', 'BYD', 'How will battery safety be managed?', 'The repairer should identify high voltage risks and establish safe procedures before work begins.', false, 'retired', 52),
  ('byd-question-4', 'BYD', 'What happens to affected safety sensors?', 'Ask how diagnostics and calibration requirements will be assessed and recorded.', false, 'retired', 53),
  ('byd-question-5', 'BYD', 'Can you manage the claim and mobility needs?', 'Confirm insurer communication, towing and loan car arrangements early.', false, 'retired', 54),
  ('lexus-question-1', 'Lexus', 'Are you officially approved by Lexus?', 'Ask for proof that the approval is current and applies to the repair facility.', false, 'retired', 55),
  ('lexus-question-2', 'Lexus', 'Will genuine OEM Lexus parts be used?', 'Confirm the parts approach before work is authorised and ask how any variation will be explained.', false, 'retired', 56),
  ('lexus-question-3', 'Lexus', 'How will safety systems be checked?', 'Ask what diagnostics and calibration steps apply to the affected Lexus model.', false, 'retired', 57),
  ('lexus-question-4', 'Lexus', 'How will colour and finish quality be controlled?', 'The repairer should explain preparation, colour matching, refinishing and final inspection.', false, 'retired', 58),
  ('lexus-question-5', 'Lexus', 'What warranty and documents will I receive?', 'Request the written warranty and retain repair and calibration documentation.', false, 'retired', 59)
